const cases={customer:{left:'Kunde',right:'Auftrag',verb:'erteilt',l:'1',r:'n',caption:'1:n-Beziehung',explanation:'Ein Kunde kann mehrere Aufträge erteilen; ein Auftrag gehört zu genau einem Kunden.',sql:'KUNDE (KundenNr PK, Name)\nAUFTRAG (AuftragsNr PK, KundenNr FK, Datum)',note:'Bei 1:n steht der Fremdschlüssel auf der n-Seite.'},course:{left:'Lernende',right:'Kurs',verb:'besucht',l:'m',r:'n',caption:'m:n-Beziehung',explanation:'Viele Lernende können viele Kurse besuchen. Die Beziehung wird relational in einer eigenen Tabelle umgesetzt.',sql:'LERNENDE (LernendenID PK)\nKURS (KursID PK)\nTEILNAHME (LernendenID FK, KursID FK, PK aus beiden)',note:'Bei m:n brauchst du üblicherweise eine Zwischentabelle mit beiden Fremdschlüsseln.'},badge:{left:'Mitarbeiter',right:'Ausweis',verb:'besitzt',l:'1',r:'1',caption:'1:1-Beziehung',explanation:'Höchstens ein Ausweis pro Mitarbeiter und höchstens ein Mitarbeiter pro Ausweis; ob ein Ausweis Pflicht ist, wird extra festgelegt.',sql:'MITARBEITER (MitarbeiterID PK)\nAUSWEIS (AusweisID PK, MitarbeiterID FK UNIQUE)',note:'Bei 1:1 erzwingt ein UNIQUE-Fremdschlüssel die Eindeutigkeit der Zuordnung; Pflichtteilnahme benötigt zusätzliche Regeln.'}};
document.getElementById('erCase').addEventListener('change',ev=>{const s=cases[ev.target.value];for(const [key,id] of [['left','erLeft'],['right','erRight'],['verb','erVerb'],['l','erCardL'],['r','erCardR'],['caption','erCaption'],['explanation','erExplanation'],['sql','erSQL'],['note','erNote']])document.getElementById(id).textContent=s[key];});
})();
(function(){'use strict';let done=new Set(),score=0;for(const q of document.querySelectorAll('.question[data-correct]')){q.querySelectorAll('button[data-choice]').forEach(b=>b.addEventListener('click',()=>{if(done.has(q))return;done.add(q);const ok=b.dataset.choice===q.dataset.correct;if(ok)score++;q.querySelectorAll('button[data-choice]').forEach(x=>{x.disabled=true;if(x.dataset.choice===q.dataset.correct)x.classList.add('correct');else if(x===b)x.classList.add('wrong')});q.querySelector('.feedback').textContent=(ok?'Richtig. ':'Nicht ganz. ')+(q.dataset.explain||'');const out=document.getElementById('quizScore');if(out)out.textContent=score+' von '+done.size+' richtig · '+done.size+' beantwortet';}));}document.getElementById('quizReset')?.addEventListener('click',()=>{score=0;done.clear();document.querySelectorAll('.question[data-correct]').forEach(q=>{q.querySelectorAll('button[data-choice]').forEach(b=>{b.disabled=false;b.classList.remove('correct','wrong')});q.querySelector('.feedback').textContent=''});document.getElementById('quizScore').textContent='Noch keine Antworten';});})();
</script></body></html>